//
// What the mock received of each kind of credential the client sends, and a call that needs none.

import assert from 'node:assert/strict'
import { after, before, test } from 'node:test'
import { Shop } from "@shop/sdk"
import { mock } from '../mock/server.mjs'

let server
let client

before(async () => {
  server = await mock()
  client = new Shop({ baseURL: server.url, apiKeyAuth: 'test-credential', bearerAuth: 'test-credential', maxRetries: 0 })
})

after(() => server.close())

/** The request the mock answered last; `null` against a server of your own. */
const last = () => server.requests?.at(-1) ?? null

test("ApiKeyAuth: sent by pets.list", async () => {
  await client.pets.list()
  const r = last()
  if (r === null) return
  assert.equal(r.headers["x-api-key"], 'test-credential')
})

test("no credential: system.health needs none", async () => {
  const none = new Shop({ baseURL: server.url, maxRetries: 0, apiKeyAuth: null, bearerAuth: null })
  await none.system.health()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, undefined)
  assert.equal(r.headers["x-api-key"], undefined)
})
